    new_msg = {'id': next_id, 'username': msg.username, 'message': msg.message, 'timestamp': datetime.now().isoformat()}
    next_id += 1
    messages.append(new_msg)
    for conn in active_connections:
        await conn.send_json(new_msg)
    return new_msg

