package main

import (
	"encoding/json"
	"net/http"
	"os"
	"sync"
	"time"

	"github.com/gorilla/websocket"
)

type Message struct {
	ID        int    `json:"id"`
	Username  string `json:"username"`
	Message   string `json:"message"`
	Timestamp string `json:"timestamp"`
}

var (
	messages []Message
	nextID   = 1
	clients  = make(map[*websocket.Conn]bool)
	mu       sync.Mutex
	upgrader = websocket.Upgrader{CheckOrigin: func(r *http.Request) bool { return true }}
)

func broadcast(msg Message) {
	mu.Lock()
	defer mu.Unlock()
	data, _ := json.Marshal(msg)
	for conn := range clients {
		conn.WriteMessage(websocket.TextMessage, data)
	}
}

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "3000"
	}

	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]string{"status": "ok"})
	})

	http.HandleFunc("/chat/send", func(w http.ResponseWriter, r *http.Request) {
		var body struct {
			Username string `json:"username"`
			Message  string `json:"message"`
		}
		json.NewDecoder(r.Body).Decode(&body)
		msg := Message{ID: nextID, Username: body.Username, Message: body.Message, Timestamp: time.Now().Format(time.RFC3339)}
		nextID++
		messages = append(messages, msg)
		broadcast(msg)
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(msg)
	})

	http.HandleFunc("/chat/messages", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(messages)
	})

	http.HandleFunc("/chat", func(w http.ResponseWriter, r *http.Request) {
		conn, _ := upgrader.Upgrade(w, r, nil)
		mu.Lock()
		clients[conn] = true
		mu.Unlock()
		defer func() {
			mu.Lock()
			delete(clients, conn)
			mu.Unlock()
			conn.Close()
		}()
		for {
			_, _, _ = conn.ReadMessage()
		}
	})

	http.ListenAndServe(":"+port, nil)
}
